  const e=.125;
  rail(-HX,-1.25,HZ-e,HZ,true);rail(1.25,HX,HZ-e,HZ,true);   // trước (có lối bậc ở giữa)
  rail(-HX,HX,-HZ,-HZ+e,true);                               // sau
