    for(const m of w.meshLOD()){m.position.set(hx+cx,0,hz+cz);m.rotation.y=a;S.add(m);meshes.push(m)}
    // va chạm: hộp AABB bao hình chữ nhật chân kệ + bảng tên sau khi xoay
