      const tx=lx+e.fx*.2+off*e.fz,ty=e.y,tz=lz+e.fz*.2-off*e.fx;          // điểm đèn chĩa tới: giữa mặt tranh
      _dir.set(tx-px,ty-py,tz-rz).normalize();
